s=open('/tmp/pypi_simple.html').read();names=re.findall(r'>([^<]+)</a>',s)
sel=sorted({n for n in names if any(p in n.lower() for p in ['dataset','crowd','landcover','land-cover','satellite','remote-sensing','remotesensing'])})
print('selected',len(sel),flush=True)
def page(n):
 try:
  u=BASE+'simple/'+urllib.parse.quote(n.lower())+'/'
  z=requests.get(u,timeout=5)
  if z.status_code!=200:return {'n':n,'e':str(z.status_code)}
  anchors=re.findall(r'<a\s+href="([^"]+)"([\s\S]*?)</a>',z.text)
  for href,rest in reversed(anchors):
   if 'data-core-metadata' in rest and '.whl' in href:
    return {'n':n,'m':urllib.parse.urljoin(u,href.split('#')[0])+'.metadata','a':urllib.parse.urljoin(u,href.split('#')[0])}
  return {'n':n,'e':'nometa'}
 except Exception as e:return {'n':n,'e':type(e).__name__}
rows=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as ex:
 futs=[ex.submit(page,n) for n in sel]
 for i,f in enumerate(concurrent.futures.as_completed(futs),1):
  rows.append(f.result())
  if i%250==0:print('pages',i,'valid',sum('m'in r for r in rows),flush=True)
print('fetch metadata',sum('m'in r for r in rows),flush=True)
def meta(r):
 if 'm' not in r:return r
 try:r['t']=requests.get(r['m'],timeout=5).text
 except Exception as e:r['e2']=type(e).__name__
 return r
out=[]
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as ex:
 futs=[ex.submit(meta,r) for r in rows]
 for i,f in enumerate(concurrent.futures.as_completed(futs),1):
  out.append(f.result())
  if i%250==0:print('meta',i,flush=True)
with open('/tmp/meta_scan.jsonl','w') as q:
 for r in out:q.write(json.dumps(r)+'\n')
hits=[]; broad=[]
for r in out:
 lo=r.get('t','').lower()
 if any(x in lo for x in ['crowdsourced mapping','max_ndvi','20150720_n','crowdsourced+mapping','crowdsourced%20mapping']):hits.append(r)
 if 'crowd' in lo and any(x in lo for x in ['mapping','land cover','land-cover','ndvi']):broad.append(r)
print('EXACT',[(r['n'],r.get('a')) for r in hits]);print('BROAD',[(r['n'],r.get('a')) for r in broad]);print('errors',sum('e'in r or 'e2'in r for r in out))
